import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { CheckCircle } from 'lucide-react';
import { tableAPI, bookingAPI } from '../api';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

export default function Booking() {
  const { isAuth } = useAuth();
  const navigate = useNavigate();
  const [tables, setTables] = useState([]);
  const [form, setForm] = useState({
    table_id: '',
    booking_date: '',
    start_time: '',
    end_time: '',
    number_of_guests: '2',
    special_requests: '',
  });
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    tableAPI.list()
      .then(r => {
        const available = r.data.filter(t => t.status === 'available');
        setTables(available);
        // Auto-select first table
        if (available.length > 0) {
          setForm(f => ({ ...f, table_id: String(available[0].id) }));
        }
      })
      .catch(() => toast.error('Could not load tables'));
  }, []);

  const handle = e => {
    const { name, value } = e.target;
    setForm(f => ({ ...f, [name]: value }));
    setErrors(prev => ({ ...prev, [name]: '' }));
  };

  const validate = () => {
    const errs = {};
    if (!form.table_id) errs.table_id = 'Please select a table';
    if (!form.booking_date) errs.booking_date = 'Please select a date';
    if (!form.start_time) errs.start_time = 'Please select start time';
    if (!form.end_time) errs.end_time = 'Please select end time';
    if (!form.number_of_guests || parseInt(form.number_of_guests) < 1)
      errs.number_of_guests = 'At least 1 guest required';
    if (form.start_time && form.end_time && form.start_time >= form.end_time)
      errs.end_time = 'End time must be after start time';
    return errs;
  };

  const today = new Date().toISOString().split('T')[0];

  const submit = async e => {
    e.preventDefault();
    if (!isAuth) { toast.error('Please login to book a table'); navigate('/login'); return; }

    const errs = validate();
    if (Object.keys(errs).length > 0) {
      setErrors(errs);
      toast.error('Please fill in all required fields');
      return;
    }

    setLoading(true);
    try {
      const payload = {
        table_id: parseInt(form.table_id),
        booking_date: form.booking_date,
        start_time: form.start_time,
        end_time: form.end_time,
        number_of_guests: parseInt(form.number_of_guests),
        special_requests: form.special_requests,
      };
      await bookingAPI.create(payload);
      setSuccess(true);
      toast.success('Table booked successfully! 🎉');
    } catch (err) {
      const errs = err.response?.data;
      if (errs && typeof errs === 'object') {
        Object.values(errs).flat().forEach(m => toast.error(m));
      } else {
        toast.error('Booking failed. Please try again.');
      }
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setSuccess(false);
    setErrors({});
    setForm({
      table_id: tables.length > 0 ? String(tables[0].id) : '',
      booking_date: '',
      start_time: '',
      end_time: '',
      number_of_guests: '2',
      special_requests: '',
    });
  };

  if (success) return (
    <div style={{ minHeight:'70vh', display:'flex', alignItems:'center', justifyContent:'center', padding:24, background:'#f5efe6' }}>
      <div style={{ background:'#fff', borderRadius:24, padding:'48px 36px', textAlign:'center', boxShadow:'0 8px 40px rgba(74,44,42,0.15)', maxWidth:420, width:'100%' }}>
        <CheckCircle size={72} color="#4caf50" />
        <h2 style={{ fontFamily:'Playfair Display, serif', fontSize:'1.9rem', margin:'20px 0 12px', color:'#2c1a1a' }}>Booking Confirmed!</h2>
        <p style={{ color:'#8d7b72', fontSize:15, marginBottom:32, lineHeight:1.7 }}>
          Your table has been reserved. We look forward to seeing you at BrewHaven!
        </p>
        <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
          <button className="btn-primary" onClick={() => navigate('/bookings')}>My Bookings</button>
          <button className="btn-outline" onClick={resetForm}>New Booking</button>
        </div>
      </div>
    </div>
  );

  return (
    <div>
      <div className="page-hero">
        <h1>Reserve Your Table</h1>
        <p>Book your perfect spot — indoor, outdoor & private rooms available.</p>
      </div>

      <div className="booking-grid">
        {/* Booking Form */}
        <div className="form-card">
          <h3 style={{ fontFamily:'Playfair Display, serif', fontSize:'1.4rem', marginBottom:24, color:'#2c1a1a' }}>
            Booking Details
          </h3>

          <form onSubmit={submit} noValidate>

            {/* Table Select */}
            <div className="form-field">
              <label className="form-label">Select Table *</label>
              <select
                name="table_id"
                value={form.table_id}
                onChange={handle}
                className="form-select"
                style={errors.table_id ? { borderColor:'#e53935' } : {}}
              >
                <option value="">-- Choose a table --</option>
                {tables.map(t => (
                  <option key={t.id} value={String(t.id)}>
                    Table {t.table_number} — {t.location} (seats {t.capacity})
                    {t.has_window_view ? ' | Window View' : ''}
                    {t.has_power_outlet ? ' | Power Outlet' : ''}
                  </option>
                ))}
              </select>
              {errors.table_id && <span style={errStyle}>{errors.table_id}</span>}
            </div>

            {/* Date & Guests */}
            <div className="form-row">
              <div className="form-field">
                <label className="form-label">Date *</label>
                <input
                  type="date"
                  name="booking_date"
                  value={form.booking_date}
                  onChange={handle}
                  min={today}
                  className="form-input"
                  style={errors.booking_date ? { borderColor:'#e53935' } : {}}
                />
                {errors.booking_date && <span style={errStyle}>{errors.booking_date}</span>}
              </div>
              <div className="form-field">
                <label className="form-label">Number of Guests *</label>
                <input
                  type="number"
                  name="number_of_guests"
                  value={form.number_of_guests}
                  onChange={handle}
                  min="1"
                  max="20"
                  className="form-input"
                  style={errors.number_of_guests ? { borderColor:'#e53935' } : {}}
                />
                {errors.number_of_guests && <span style={errStyle}>{errors.number_of_guests}</span>}
              </div>
            </div>

            {/* Start & End Time */}
            <div className="form-row">
              <div className="form-field">
                <label className="form-label">Start Time *</label>
                <input
                  type="time"
                  name="start_time"
                  value={form.start_time}
                  onChange={handle}
                  className="form-input"
                  style={errors.start_time ? { borderColor:'#e53935' } : {}}
                />
                {errors.start_time && <span style={errStyle}>{errors.start_time}</span>}
              </div>
              <div className="form-field">
                <label className="form-label">End Time *</label>
                <input
                  type="time"
                  name="end_time"
                  value={form.end_time}
                  onChange={handle}
                  className="form-input"
                  style={errors.end_time ? { borderColor:'#e53935' } : {}}
                />
                {errors.end_time && <span style={errStyle}>{errors.end_time}</span>}
              </div>
            </div>

            {/* Special Requests */}
            <div className="form-field">
              <label className="form-label">Special Requests <span style={{ color:'#8d7b72', fontWeight:400 }}>(optional)</span></label>
              <textarea
                name="special_requests"
                value={form.special_requests}
                onChange={handle}
                placeholder="Birthday celebration? Anniversary? High chair needed?"
                rows={3}
                className="form-textarea"
              />
            </div>

            {!isAuth && (
              <div style={{ background:'#fff3e0', borderRadius:10, padding:'12px 16px', fontSize:14, color:'#4a2c2a', marginBottom:18, border:'1px solid #ffe0b2' }}>
                🔒 Please <a href="/login" style={{ color:'#d4762a', fontWeight:700 }}>login</a> to make a booking.
              </div>
            )}

            <button type="submit" disabled={loading} className="submit-btn">
              {loading ? '⏳ Booking...' : '✓ Confirm Booking'}
            </button>
          </form>
        </div>

        {/* Info Panel */}
        <div>
          <div className="form-card" style={{ marginBottom:20 }}>
            <h3 style={{ fontFamily:'Playfair Display, serif', fontSize:'1.2rem', marginBottom:18, color:'#2c1a1a' }}>
              Table Options
            </h3>
            {[
              { icon:'🪟', title:'Window Seats', desc:'Enjoy city views with natural light', seats:'2' },
              { icon:'🛋️', title:'Indoor Tables', desc:'Comfortable air-conditioned seating', seats:'2–6' },
              { icon:'🌿', title:'Outdoor Patio', desc:'Open-air seating for fresh air lovers', seats:'2–4' },
              { icon:'🤝', title:'Conference Room', desc:'Perfect for meetings & group sessions', seats:'8' },
            ].map(t => (
              <div key={t.title} style={{ display:'flex', gap:12, marginBottom:14, padding:12, borderRadius:10, background:'#f5efe6', alignItems:'flex-start' }}>
                <span style={{ fontSize:24, flexShrink:0 }}>{t.icon}</span>
                <div>
                  <div style={{ fontWeight:700, fontSize:14, color:'#2c1a1a' }}>
                    {t.title} <span style={{ fontSize:12, color:'#8d7b72', fontWeight:400 }}>({t.seats} seats)</span>
                  </div>
                  <div style={{ fontSize:13, color:'#8d7b72', marginTop:2 }}>{t.desc}</div>
                </div>
              </div>
            ))}
          </div>

          <div style={{ background:'#1a0f0f', color:'#f5efe6', borderRadius:18, padding:'22px 24px' }}>
            <h4 style={{ fontFamily:'Playfair Display, serif', fontSize:'1.1rem', marginBottom:16 }}>⏰ Opening Hours</h4>
            <div style={{ display:'flex', justifyContent:'space-between', marginBottom:10, fontSize:14, flexWrap:'wrap', gap:6 }}>
              <span style={{ opacity:0.8 }}>Monday – Friday</span>
              <strong>7:00 AM – 10:00 PM</strong>
            </div>
            <div style={{ display:'flex', justifyContent:'space-between', fontSize:14, flexWrap:'wrap', gap:6 }}>
              <span style={{ opacity:0.8 }}>Saturday – Sunday</span>
              <strong>8:00 AM – 11:00 PM</strong>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

const errStyle = {
  color: '#e53935',
  fontSize: 12,
  marginTop: 5,
  display: 'block',
  fontWeight: 600,
};
